document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("youtube-monetization-form");e&&e.addEventListener("submit",function(e){e.preventDefault();const n=parseFloat(document.getElementById("subscribers").value),t=parseFloat(document.getElementById("monthlyViews").value),i=parseFloat(document.getElementById("avgViewDuration").value)/100,r=(parseInt(document.getElementById("videosPerMonth").value),document.getElementById("contentCategory").value),o=document.getElementById("audienceLocation").value,a=parseFloat(document.getElementById("engagementRate").value)/100,d="true"===document.getElementById("monetizationEnabled").value,s="true"===document.getElementById("membershipsEnabled").value,l=parseInt(document.getElementById("sponsorshipRate").value)||0,m="true"===document.getElementById("merchandiseEnabled").value,u=parseFloat(document.getElementById("monthlyGrowthRate").value)/100,g=parseInt(document.getElementById("projectionMonths").value),c={gaming:{tier1:2.5,tier2:1.8,tier3:1.2,tier4:.8},tech:{tier1:4,tier2:2.8,tier3:1.8,tier4:1.2},lifestyle:{tier1:2,tier2:1.4,tier3:.9,tier4:.6},entertainment:{tier1:1.8,tier2:1.3,tier3:.8,tier4:.5},business:{tier1:5,tier2:3.5,tier3:2.2,tier4:1.5},health:{tier1:3.2,tier2:2.2,tier3:1.4,tier4:.9},music:{tier1:1.5,tier2:1.1,tier3:.7,tier4:.4},comedy:{tier1:1.8,tier2:1.3,tier3:.8,tier4:.5}}[r][o];let h=0;if(d){h=t/1e3*(.7*c)}let b=0;if(s&&n>=1e3){b=n*Math.min(a/2,.01)*4.99}let p=0;if(l>0&&n>=1e4){p=l*(t/1e3)*{gaming:2,tech:4,lifestyle:2.5,entertainment:1.5,business:5,health:3,music:1.5,comedy:1.5}[r]}let v=0;d&&(v=n*a*.02);let f=0;if(m&&n>=1e3){f=n*Math.min(a,.02)*25}const y=h+b+p+v+f;let $=n,M=t;for(let e=1;e<=g;e++)$*=1+u,M*=1+u;let x=0;if(d||$>=1e3&&M>=4e3){x=M/1e3*(.7*c)}let E=0;if(s||$>=1e3){E=$*Math.min(a/2,.01)*4.99}let w=0;if($>=1e4){const e={gaming:2,tech:4,lifestyle:2.5,entertainment:1.5,business:5,health:3,music:1.5,comedy:1.5}[r];w=Math.min(l+Math.floor($/5e4),8)*(M/1e3)*e}let F=$*a*.02,I=0;if(m||$>=5e3){I=$*Math.min(a,.02)*25}const S=x+E+w+F+I,B=12*y,L=12*S;let z="",C="";!d&&(n<1e3||t<4e3)?(z="🔄 Building to Partner Program eligibility",C="warning"):y<100?(z="🌱 Early monetization stage",C="info"):y<1e3?(z="📈 Growing revenue streams",C="info"):(z="💰 Strong monetization",C="success");document.getElementById("youtube-monetization-result").innerHTML=`\n      <h3>📺 YouTube Monetization Analysis</h3>\n      \n      <div class="insight-cards">\n        <div class="insight-card ${C}">\n          <h6>💰 Current Monthly Revenue</h6>\n          <div class="big-number">$${Math.round(y).toLocaleString()}</div>\n          <p>${z}<br>\n          Annual: $${Math.round(B).toLocaleString()}<br>\n          RPM: $${d?(h/t*1e3).toFixed(2):"0.00"}</p>\n        </div>\n        \n        <div class="insight-card success">\n          <h6>🚀 Projected Revenue (${g}M)</h6>\n          <div class="big-number">$${Math.round(S).toLocaleString()}</div>\n          <p>Monthly with ${(100*u).toFixed(1)}% growth<br>\n          Annual: $${Math.round(L).toLocaleString()}<br>\n          ${Math.round((S-y)/Math.max(y,1)*100)}% increase</p>\n        </div>\n        \n        <div class="insight-card info">\n          <h6>👥 Channel Growth</h6>\n          <div class="big-number">${Math.round($).toLocaleString()}</div>\n          <p>Projected subscribers<br>\n          Views: ${Math.round(M/1e3)}K/month<br>\n          Growth: +${Math.round(($-n)/n*100)}%</p>\n        </div>\n      </div>\n\n      <div style="margin-top: 2rem; padding: 1.5rem; background: #f8f9fa; border-radius: 12px;">\n        <h4>💸 Revenue Breakdown Analysis</h4>\n        \n        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 1.5rem; margin-top: 1rem;">\n          <div>\n            <strong>📊 Current Revenue Sources:</strong><br>\n            Ad Revenue: $${Math.round(h).toLocaleString()} (${(h/Math.max(y,1)*100).toFixed(1)}%)<br>\n            Sponsorships: $${Math.round(p).toLocaleString()} (${(p/Math.max(y,1)*100).toFixed(1)}%)<br>\n            Memberships: $${Math.round(b).toLocaleString()} (${(b/Math.max(y,1)*100).toFixed(1)}%)<br>\n            Merchandise: $${Math.round(f).toLocaleString()} (${(f/Math.max(y,1)*100).toFixed(1)}%)<br>\n            Super Chat/Thanks: $${Math.round(v).toLocaleString()} (${(v/Math.max(y,1)*100).toFixed(1)}%)\n          </div>\n          \n          <div>\n            <strong>🎯 Channel Metrics:</strong><br>\n            Subscribers: ${n.toLocaleString()}<br>\n            Monthly views: ${(t/1e3).toFixed(0)}K<br>\n            Avg view duration: ${(100*i).toFixed(1)}%<br>\n            Engagement rate: ${(100*a).toFixed(1)}%<br>\n            Content category: ${r}<br>\n            Audience: ${o.replace("tier","Tier ")} countries\n          </div>\n        </div>\n        \n        <div style="margin-top: 1.5rem; display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 1rem;">\n          ${!d&&n<1e3?`\n          <div style="padding: 1rem; background: #fff3cd; border-radius: 8px; text-align: center;">\n            <strong>🎯 Next Milestone</strong><br>\n            ${1e3-n} more subscribers<br>\n            for Partner Program\n          </div>\n          `:""}\n          \n          <div style="padding: 1rem; background: #e8f5e8; border-radius: 8px; text-align: center;">\n            <strong>💡 Optimization</strong><br>\n            Focus on ${i<.4?"watch time":a<.03?"engagement":"consistency"}\n          </div>\n          \n          <div style="padding: 1rem; background: #e3f2fd; border-radius: 8px; text-align: center;">\n            <strong>📈 Growth Rate</strong><br>\n            ${(100*u).toFixed(1)}% monthly<br>\n            ${(100*(Math.pow(1+u,12)-1)).toFixed(0)}% annually\n          </div>\n        </div>\n        \n        <div style="margin-top: 1rem; padding: 1rem; background: ${S>=1e3?"#d4edda":S>=100?"#fff3cd":"#f8d7da"}; border-radius: 8px; border-left: 4px solid ${S>=1e3?"#28a745":S>=100?"#ffc107":"#dc3545"};">\n          <strong>💡 Monetization Strategy:</strong><br>\n          ${S>=1e3?"🎉 Excellent earning potential! Diversify income streams, consider premium content, and explore brand partnerships. Focus on audience retention and community building.":S>=100?"✅ Good foundation for growth! Optimize ad placement, improve engagement, and start building email list. Consider affiliate marketing and product creation.":"📈 Focus on growth fundamentals: consistent uploads, SEO optimization, audience engagement, and content quality. Monetization will follow audience growth."}<br><br>\n          \n          <strong>🚀 Revenue Optimization Tips:</strong><br>\n          • ${i<.4?"Improve video retention with better hooks and pacing":"Create longer videos (8+ min) for mid-roll ads"}<br>\n          • ${a<.03?"Boost engagement with CTAs and community posts":"Leverage high engagement for brand partnerships"}<br>\n          • ${0===p&&n>=1e4?"Start reaching out to brands for sponsorship deals":"Continue building audience for sponsor appeal"}\n        </div>\n      </div>\n    `})});